elements <- c('wind', 'visibility', 'weather', 'cloud')
overlay <- function(base, change, replace = FALSE) {
    s <- list()
    for (k in elements) {
        if (k %in% names(change)) s[k] <- change[k] else if (!replace && k %in% names(base)) s[k] <- base[k]
    }
    s
